#include "backend/metal/device.hpp"

#include <cstdio>
#include <cstdlib>
#include <cstring>

#include "metal_kernels_src.h"  // kMetalKernelsSource: kernels.metal as a string (generated by metal.cmake)

namespace ragon::metal {

[[noreturn]] static void die(const char* what, NSError* err) {
  std::fprintf(stderr, "metal: %s: %s\n", what, err ? [[err localizedDescription] UTF8String] : "(no detail)");
  std::exit(2);
}

void Queue::open() {
  dev = MTLCreateSystemDefaultDevice();
  if (!dev) die("no Metal device", nil);
  q = [dev newCommandQueue];
  MTLCompileOptions* opts = [MTLCompileOptions new];
  opts.mathMode = MTLMathModeSafe;
  NSError* err = nil;
  lib = [dev newLibraryWithSource:[NSString stringWithUTF8String:kMetalKernelsSource] options:opts error:&err];
  if (!lib) die("kernel compile", err);
}

id<MTLComputePipelineState> Queue::pipe(const char* name, uint32_t rows) {
  std::string key = std::string(name) + "/" + std::to_string(rows);
  auto it = pipes.find(key);
  if (it != pipes.end()) return it->second;
  NSError* err = nil;
  id<MTLFunction> fn;
  NSString* n = [NSString stringWithUTF8String:name];
  if (rows) {
    MTLFunctionConstantValues* cv = [MTLFunctionConstantValues new];
    [cv setConstantValue:&rows type:MTLDataTypeUInt atIndex:0];
    fn = [lib newFunctionWithName:n constantValues:cv error:&err];
  } else {
    fn = [lib newFunctionWithName:n];
  }
  if (!fn) die(name, err);
  id<MTLComputePipelineState> p = [dev newComputePipelineStateWithFunction:fn error:&err];
  if (!p) die(name, err);
  pipes[key] = p;
  return p;
}

View Queue::alloc(size_t bytes) {
  id<MTLBuffer> b = [dev newBufferWithLength:(bytes ? bytes : 16) options:MTLResourceStorageModeShared];
  if (!b) die("buffer allocation", nil);
  std::memset([b contents], 0, [b length]);
  return {b, 0};
}

id<MTLComputeCommandEncoder> Queue::encoder() {
  if (!cb) cb = [q commandBuffer];
  if (!enc) enc = [cb computeCommandEncoderWithDispatchType:MTLDispatchTypeSerial];
  return enc;
}

double Queue::sync() {
  if (enc) [enc endEncoding];
  enc = nil;
  if (!cb) return 0;
  [cb commit];
  [cb waitUntilCompleted];
  double t = [cb GPUEndTime] - [cb GPUStartTime];
  if ([cb status] == MTLCommandBufferStatusError) die("command buffer", [cb error]);
  cb = nil;
  return t;
}

}  // namespace ragon::metal
